import { encodeAbiParameters, keccak256 } from "viem";
import { MarketParams, marketParamsAbi, } from "../../market/index.js";
import { CapacityLimitReason } from "../../utils.js";
import { VaultV2Adapter } from "./VaultV2Adapter.js";
export class VaultV2MorphoMarketV1Adapter extends VaultV2Adapter {
    static adapterId(address) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }], ["this", address]));
    }
    static collateralId(address) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }], ["collateralToken", address]));
    }
    static marketParamsId(address, params) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }, marketParamsAbi], ["this/marketParams", address, params]));
    }
    marketParamsList;
    constructor({ marketParamsList, ...vaultV2Adapter }) {
        super({
            ...vaultV2Adapter,
            type: "VaultV2MorphoMarketV1Adapter",
            adapterId: VaultV2MorphoMarketV1Adapter.adapterId(vaultV2Adapter.address),
        });
        this.marketParamsList = marketParamsList.map((params) => new MarketParams(params));
    }
    ids(params) {
        return [
            this.adapterId,
            VaultV2MorphoMarketV1Adapter.collateralId(params.collateralToken),
            VaultV2MorphoMarketV1Adapter.marketParamsId(this.address, params),
        ];
    }
}
export class AccrualVaultV2MorphoMarketV1Adapter extends VaultV2MorphoMarketV1Adapter {
    positions;
    constructor(adapter, positions) {
        super(adapter);
        this.positions = positions;
    }
    realAssets(timestamp) {
        return this.positions.reduce((total, position) => total + position.accrueInterest(timestamp).supplyAssets, 0n);
    }
    maxDeposit(_data, assets) {
        return {
            value: BigInt(assets),
            limiter: CapacityLimitReason.balance,
        };
    }
    maxWithdraw(data) {
        const marketId = MarketParams.fromHex(data).id;
        const position = this.positions.find(
        // biome-ignore lint/nursery/noShadow: TODO rename to avoid shadowing
        (position) => position.marketId === marketId);
        return (position?.market?.getWithdrawCapacityLimit(position) ?? {
            value: 0n,
            limiter: CapacityLimitReason.position,
        });
    }
}
